// --- GRADAZIONE DEL COLORE, SIMMETRICA RISPETTO A PI/4 ---
// Modula il COLORE PRINCIPALE della superficie (quello dello slider, verde per
// default) senza sostituirlo. Il motore compone finalRGB = ubuf.color * questo
// valore, quindi restituendo un GRIGIO si ottiene una gradazione del colore
// scelto, qualunque esso sia: cambiando colore dallo slider la gradazione lo
// segue.
//
// La gradazione dipende dal raggio r del toro di QUESTA mesh, ricostruito con la
// stessa formula chiusa del corpo a partire da `mesh` ed E. E' SIMMETRICA
// rispetto a PI/4: l'equatore (il toro di Clifford) resta a piena intensita' e i
// tori si scuriscono allontanandosene, con i due membri di ogni coppia
// simmetrica identici.
//
//     d = |r - PI/4| / (PI/4)      0 sull'equatore, -> 1 verso le fibre polari
//
// NB: PI/2 e' scritto come 2*P4 e NON come 1.57079633. Le due costanti
// troncate non sono esattamente l'una il doppio dell'altra (differiscono di
// 1e-8), e questo rendeva i due membri di una coppia simmetrica diversi di
// 1.27e-08: sotto l'epsilon di float32, quindi invisibile, ma con 2*P4 la
// simmetria e' esatta al bit e non dipende dalla precisione della GPU.
float P4 = 0.78539816;
float P2 = 2.0 * P4;

float Ne = clamp(floor(clamp(E, 1.0, 5.0) + 0.5), 1.0, 5.0);
float mm = floor(Ne * 0.5);
float odd = Ne - 2.0 * mm;
float isEq = odd * (1.0 - step(0.5, mesh));
float j = mesh - odd;
float kk = floor(j * 0.5) + 1.0;
float sg = j - 2.0 * floor(j * 0.5);
float rb = kk * P4 / (mm + 1.0);
float rp = mix(rb, P2 - rb, sg);
float rr = mix(rp, P4, isEq);

// Distanza normalizzata dall'equatore: 0 = PI/4, 1 = fibra polare.
float d = abs(rr - P4) / P4;

// Contrasto sullo slider A: 0 = tutti uguali (nessuna gradazione),
// 1 = scala piena. Il fondo non scende sotto 0.35 per non annerire del tutto
// i tori piu' esterni, che altrimenti diventerebbero indistinguibili.
float amt = clamp(A, 0.0, 1.0);
float lum = 1.0 - amt * 0.65 * d;

return u_col1 * lum;
